#!/usr/bin/env node

/**
 * Test/validation script - parses local library.html file
 * Useful for testing without fetching from internet
 * 
 * Generated by Claude Haiku 4.5
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

let cheerio;
try {
  cheerio = (await import('cheerio')).default;
  if (!cheerio) {
    const module = await import('cheerio');
    cheerio = module.load ? module : module.default;
  }
  if (!cheerio || !cheerio.load) {
    throw new Error('Cheerio does not have load method');
  }
} catch (e) {
  console.error('Error importing cheerio:', e.message);
  process.exit(1);
}

const INPUT_FILE = path.join(__dirname, 'library.html');
const OUTPUT_FILE = path.join(__dirname, '..', '..', 'src', 'app', 'onshape', 'featurescript-library-test.json');

/**
 * Parse parameter table from HTML
 */
function parseParameterTable($, table) {
  const params = [];
  const rows = $(table).find('tbody tr, tr');
  
  rows.each((i, row) => {
    const cells = $(row).find('td, th');
    if (cells.length >= 2) {
      const param = {
        name: $(cells[0]).text().trim(),
        type: $(cells[1]).text().trim(),
        description: cells[2] ? $(cells[2]).text().trim() : ''
      };
      
      if (param.name && !param.name.includes('Parameter') && !param.name.includes('Type')) {
        params.push(param);
      }
    }
  });
  
  return params;
}

/**
 * Parse a node signature element (function/type definition)
 */
function parseNodeSignature($, elem) {
  const $elem = $(elem);
  
  // Get symbol name
  const name = $elem.find('.fs-symbol-name').first().text().trim();
  
  // Get symbol descriptor (type, predicate, function, etc.)
  const descriptor = $elem.find('.fs-symbol-descriptor').first().text().trim();
  
  // Get function arguments
  const functionArgs = $elem.find('.fs-function-arguments').first().text().trim();
  
  // Get return type
  const returnInfo = $elem.find('.fs-function-return').first().text().trim();
  
  // Get description from next doc-content or preceding text
  let description = '';
  const docContent = $elem.next('.fs-doc-content, div');
  if (docContent.length > 0) {
    description = docContent.find('p').first().text().trim();
    if (!description) {
      description = docContent.text().trim().substring(0, 200);
    }
  }
  
  // Parse parameter tables in doc content
  const parameters = [];
  if (docContent.length > 0) {
    docContent.find('table').each((i, table) => {
      const tableParams = parseParameterTable($, table);
      parameters.push(...tableParams);
    });
  }
  
  return {
    name,
    descriptor,
    signature: functionArgs,
    returnType: returnInfo.replace('returns', '').trim(),
    description,
    parameters
  };
}

/**
 * Parse a file section (fs-file)
 */
function parseFileSection($, fileElem) {
  const $file = $(fileElem);
  
  // Get file header
  const fileName = $file.find('.file-header').first().text().trim();
  
  // Get file description (first paragraph after header)
  const fileDesc = $file.find('p').first().text().trim();
  
  // Parse all node signatures in this file
  const entries = [];
  $file.find('p.node-signature').each((i, elem) => {
    try {
      const entry = parseNodeSignature($, elem);
      if (entry.name) {
        entries.push(entry);
      }
    } catch (error) {
      // Skip parsing errors
    }
  });
  
  return {
    fileName,
    description: fileDesc,
    entries
  };
}

/**
 * Main parsing function for local file
 */
async function parseLocalFile() {
  try {
    // Check if file exists
    if (!fs.existsSync(INPUT_FILE)) {
      throw new Error(`File not found: ${INPUT_FILE}`);
    }
    
    console.log(`Reading local library.html...`);
    const html = fs.readFileSync(INPUT_FILE, 'utf-8');
    console.log(`Loaded ${(html.length / 1024).toFixed(2)} KB`);
    
    const $ = cheerio.load(html);
    
    // Parse categories from sidebar
    const categories = [];
    const categoryMap = new Map();
    
    // Find all fs-section-heading elements in sidebar
    const headings = $('.fs-sidebar .fs-section-heading');
    console.log(`\nFound ${headings.length} category headings in sidebar`);
    
    headings.each((i, heading) => {
      const categoryName = $(heading).text().trim();
      const categoryId = categoryName.toLowerCase().replace(/\s+/g, '-');
      
      const category = {
        id: categoryId,
        name: categoryName,
        files: []
      };
      
      categoryMap.set(categoryId, category);
      categories.push(category);
      console.log(`  [${i + 1}] ${categoryName}`);
    });
    
    // Parse all fs-category sections
    const categoryElems = $('.fs-doc-body .fs-category');
    console.log(`\nFound ${categoryElems.length} category sections in body`);
    
    categoryElems.each((i, catElem) => {
      const categoryId = $(catElem).attr('id')?.replace('category-', '').toLowerCase().replace(/\s+/g, '-');
      const category = categoryMap.get(categoryId);
      if (!category) return;
      
      const fileElems = $(catElem).find('.fs-file');
      console.log(`  ${category.name}: ${fileElems.length} files`);
      
      // Parse all file sections in this category
      fileElems.each((j, fileElem) => {
        const fileData = parseFileSection($, fileElem);
        if (fileData.entries.length > 0 || fileData.fileName) {
          category.files.push(fileData);
        }
      });
    });
    
    // Build final JSON structure
    const documentation = {
      source: 'local/library.html',
      fetchedAt: new Date().toISOString(),
      categories,
      metadata: {
        totalCategories: categories.length,
        totalFiles: categories.reduce((sum, cat) => sum + cat.files.length, 0),
        totalEntries: categories.reduce((sum, cat) => 
          sum + cat.files.reduce((fsum, file) => fsum + file.entries.length, 0), 0
        )
      }
    };
    
    // Ensure output directory exists
    const outputDir = path.dirname(OUTPUT_FILE);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }
    
    // Write JSON file
    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(documentation, null, 2), 'utf-8');
    console.log(`\n✓ Documentation saved to ${OUTPUT_FILE}`);
    console.log(`  Categories: ${documentation.metadata.totalCategories}`);
    console.log(`  Files: ${documentation.metadata.totalFiles}`);
    console.log(`  Entries: ${documentation.metadata.totalEntries}`);
    
    // Print sample entries
    if (categories.length > 0 && categories[0].files.length > 0) {
      const sampleFile = categories[0].files[0];
      console.log(`\nSample file: ${sampleFile.fileName}`);
      if (sampleFile.entries.length > 0) {
        const sampleEntry = sampleFile.entries[0];
        console.log(`  Entry: ${sampleEntry.name}`);
        console.log(`  Descriptor: ${sampleEntry.descriptor}`);
        console.log(`  Signature: ${sampleEntry.signature.substring(0, 100)}...`);
      }
    }
    
    return documentation;
  } catch (error) {
    console.error('✗ Error parsing local file:', error.message);
    process.exit(1);
  }
}

// Run immediately
await parseLocalFile();
